public class StrictThermostatTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            StrictThermostat strict = new StrictThermostat(20);
            check("a legal start value is kept", 20, strict.getTarget());
            check("out of range start falls back to 18", 18, new StrictThermostat(30).getTarget());
            check("odd start falls back to 18", 18, new StrictThermostat(21).getTarget());
            check("below range start falls back to 18", 18, new StrictThermostat(2).getTarget());

            check("odd value refused", false, strict.setTarget(17));
            check("target survives a refused set", 20, strict.getTarget());
            check("even value inside the range accepted", true, strict.setTarget(22));
            check("target after an accepted set", 22, strict.getTarget());
            check("value the parent likes but this class does not", false, strict.setTarget(30));

            Thermostat asBase = strict;
            check("the stricter hook still wins through a base reference",
                    false, asBase.setTarget(36));
            check("target unchanged through the base reference", 22, asBase.getTarget());

            Thermostat plain = new Thermostat(20);
            check("the parent class itself is unchanged", true, plain.setTarget(36));

            check("nudge by 2", 24, strict.nudge(2));
            check("nudge by 1 is refused", 24, strict.nudge(1));
            check("nudge past the ceiling is refused", 24, strict.nudge(6));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

