 *
 * The target is private and setTarget is final, so the ONLY way a subclass can
 * change what counts as a legal setting is by overriding the allows() hook.
 */
class Thermostat {

    private int target;

    Thermostat(int target) {
        this.target = (target >= 0 && target <= 40) ? target : 20;
    }

    public final boolean setTarget(int value) {
        if (!allows(value)) {
            return false;
        }
        target = value;
        return true;
    }

    public final int getTarget() {
        return target;
    }

    /** Hook: which values this thermostat will accept. */
    protected boolean allows(int value) {
        return value >= 0 && value <= 40;
    }
}

public class StrictThermostat extends Thermostat {

    public StrictThermostat(int value) {
        super(value);
        if (!setTarget(value)) {
            setTarget(18);
        }
    }

    @Override
    protected boolean allows(int value) {
        return super.allows(value) && value >= 15 && value <= 25 && value % 2 == 0;
    }

    public int nudge(int delta) {
        setTarget(getTarget() + delta);
        return getTarget();
    }
}
